def build_extra(d):
    d.add_heading('Stitching Details, orthogonal distance regression', level=2)
    add_runs(d.add_paragraph(), STITCH['where'], size=9, italic=True, color=RGBColor(0x60, 0x60, 0x60))
    label(d, 'IN-TEXT PARAGRAPHS')
    for t in STITCH['pars']:
        p = d.add_paragraph(); add_runs(p, t, size=11)
        p.paragraph_format.first_line_indent = Pt(18); p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    label(d, 'NOTES FOR HARLAN')
    for n in STITCH['notes']:
        add_runs(d.add_paragraph(style='List Bullet'), n, size=9, italic=True)
    d.add_heading('Drop-in replacements for draft-v3', level=2)
    for rid, where, old, new in REPL:
        p = d.add_paragraph(); add_runs(p, f'<b>{rid}.</b> {where}.', size=10)
        p = d.add_paragraph(); add_runs(p, 'Current. ' + old, size=10, italic=True, color=RGBColor(0x80, 0x80, 0x80))
        p.paragraph_format.left_indent = Pt(18)
        p = d.add_paragraph(); add_runs(p, 'Replace with. ' + new, size=10)
        p.paragraph_format.left_indent = Pt(18)
    d.add_heading('Citations', level=2)
    add_runs(d.add_paragraph(), 'In references.bib, cited as [Author Year], with the BibTeX key. The bib also holds duplicate entries for Henke 1993, Capelli 2016, Passler and Paarmann, Pasquali 2014, Starostin 2025, and Watts 2011 that are worth merging before the bibliography is built.', size=10)
    for a, k in CITE_IN:
        add_runs(d.add_paragraph(style='List Bullet'), f'{a}, {k}', size=9.5)
    add_runs(d.add_paragraph(), 'Not in references.bib. BibTeX for each is in citations-to-add.bib beside this file. Check the DOIs on import.', size=10)
    for c in CITE_ADD:
        add_runs(d.add_paragraph(style='List Bullet'), c, size=9.5)


# ---------------------------------------------------------------- writer
TOK = re.compile(r'(<b>|</b>|_\{[^}]*\}|\^\{[^}]*\})')

def add_runs(p, text, size=11, italic=False, bold=False, color=None):
    b = bold
    for part in TOK.split(text):
        if not part:
            continue
        if part == '<b>':
            b = True; continue
        if part == '</b>':
            b = bold; continue
        sub = part.startswith('_{'); sup = part.startswith('^{')
        r = p.add_run(part[2:-1] if (sub or sup) else part)
        r.bold = b; r.italic = italic; r.font.size = Pt(size)
        if sub: r.font.subscript = True
        if sup: r.font.superscript = True
        if color: r.font.color.rgb = color
    return p

def label(d, text):
    p = d.add_paragraph(); r = p.add_run(text); r.bold = True; r.font.size = Pt(9)
    r.font.color.rgb = RGBColor(0x80, 0x80, 0x80)
    p.paragraph_format.space_after = Pt(2)

def build(out):
    d = docx.Document()
    st = d.styles['Normal']; st.font.name = 'Arial'; st.font.size = Pt(11)
    d.add_heading('Figure captions and in-text paragraphs', level=1)
    add_runs(d.add_paragraph(),
        'Revision 6, 6 November 2026. Covers the sixteen figures in figs/new-v2, with the contradictions flagged in revision 5 resolved, Figs. 2.7d and 5.2b and d rebuilt, citations checked against references.bib, the Stitching Details text rewritten around orthogonal distance regression, and a list of drop-in replacements for draft-v3 at the end. Each entry gives the caption, the paragraph that introduces the figure in the body text with its placement in draft-v3, and notes for Harlan that are not part of either. '
        'Captions open with a title sentence and give each panel, or a group of panels, one or two sentences that state what is plotted and how to read it. Interpretation and the numbers that carry the argument live in the in-text paragraph. '
        'Figure numbers are the working numbers from the figure plan. Removing Figs. 2.4, 2.8, and 2.10 will renumber Chapter 2 once captions use chapter-number fields (T0.2), so every "Fig." call-out here should become a Word cross-reference (T0.3). Citations are given as [Author Year]. Every one is either in references.bib (key listed at the end) or in citations-to-add.bib beside this file.', size=10, italic=True)
    for f in F:
        d.add_heading(f'Figure {f["num"]}', level=2)
        add_runs(d.add_paragraph(), f'{f["file"]}. {f["where"]}', size=9, italic=True,
                 color=RGBColor(0x60, 0x60, 0x60))
        label(d, 'CAPTION')
        p = d.add_paragraph(); add_runs(p, f'<b>Figure {f["num"]}</b> ' + f['cap'], size=10.5)
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        label(d, 'IN-TEXT PARAGRAPH')
        p = d.add_paragraph(); add_runs(p, f['par'], size=11)
        p.paragraph_format.first_line_indent = Pt(18); p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        if f['notes']:
            label(d, 'NOTES FOR HARLAN')
            for n in f['notes']:
                add_runs(d.add_paragraph(style='List Bullet'), n, size=9, italic=True)
    build_extra(d)
    d.save(out)

if __name__ == '__main__':
    build(sys.argv[1] if len(sys.argv) > 1 else 'figure-captions-v4.docx')
